quests[97662] = { id = 97662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winds of Tok'jara", description = "<As your hand closes around this fragile feather, a spectral wind echoes through the vaults.\n\nWith it, you feel the weight of your spirit's corrosion lift, as if you could simply spread your wings and fly out of this cursed place.\n\nYou can't, of course. But Er'inye might be interested in studying it.>", sourceObjective = "Bring the Feather of Tok'jara to Er'inye.", completion = "Hmph. Dere are powers lurking in dese vaults that even I am unaware of.", sourceObjectiveStatus = "unverified-source-field" }
quests[97668] = { id = 97668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Watchful Gaze of Szarith", description = "<Clutching the serpentine eyeball, you feel a new awareness creeping up the back of your neck.\n\nThe Eggs of Ula'tek. By the hundreds. You can sense their every twitching presence, waiting to burst into vile venom and more of her wretched spawn.\n\nYou wish you could toss it into the deepest crypt, but its power is undeniably potent. Er'inye would be interested in studying it.>", sourceObjective = "Bring the Eye of Szarith to Er'inye.", completion = "<Er'inye chuckles.>\n\nYou brought dis all de way here because you thought I would find it interesting? Well I do.", sourceObjectiveStatus = "unverified-source-field" }
quests[97669] = { id = 97669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Luck of the Bound Spirit", description = "<You hold a simple lynx's paw, worn by time and worry, that the spirit left as a parting gift.\n\nThough it holds no magical properties of its own, it is swollen with the hopes and fears of every bound spirit that crossed its path in this miserable place.\n\nThe result is quite potent, if emotionally harrowing. Er'inye would likely be interested in studying it.>", sourceObjective = "Bring the Lynx Paw to Er'inye.", completion = "Eugh. I do not like this one, though I cannot deny its power.", sourceObjectiveStatus = "unverified-source-field" }
quests[97670] = { id = 97670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", sourceObjective = "Zul'jarra awards those who are loyal and true. Thank you, hash'ura.", sourceObjectiveStatus = "unverified-source-field" }
quests[97672] = { id = 97672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl", sourceObjective = "Zul'jarra awards those who are loyal and true. Thank you, hash'ura.", sourceObjectiveStatus = "unverified-source-field" }
quests[97673] = { id = 97673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trove of Voidlight Marl", sourceObjective = "Zul'jarra awards those who are loyal and true. Thank you, hash'ura.", sourceObjectiveStatus = "unverified-source-field" }
quests[97910] = { id = 97910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash through your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", sourceObjective = "Complete any dungeon on Mythic 2 or higher difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[97945] = { id = 97945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Catalyst's Shadow", sourceObjective = "Speak with Orin Straylight in Silvermoon.", completion = "Ah, so you spoke with Decimus? It looks like we're on our own now. Better get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[97978] = { id = 97978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prismatic Potential", description = "Greetings, {class}. Our mutual friend explained everything to us. Don't worry, my shade and I took to Decimus' voidweaving like fish to water.\n\nWe had an idea. The Catalyst's transformative energies are immense and span the breadth of known elemental forces.\n\nIf I can learn to isolate the void from that spectrum of power, I could use it to weave Nebulous Voidcores just as Decimus did with the Voidforge.\n\nWe are no domanaar, though. We need practice.", sourceObjective = "Collect 10 Elementary Voidcore Shards from Midnight Season 2 raid bosses, Bountiful Delves, Mythic+ dungeons, and Nightmare Prey Hunts to help Orin with his Catalyst research.\n\nThe Catalyst will grant access to additional Nebulous Voidcores, used to obtain powerful items from raid bosses, Mythic+ dungeons, Bountiful delves, and Nightmare Prey.", progress = "Do you have those Elementary Voidcore Shards?", completion = "I hope it wasn't too difficult to come by these Elementary Voidcore Shards. Now that we have them, I can continue my research into the void potential of the Catalyst's power. This will take a while, so check back with me later.", sourceObjectiveStatus = "unverified-source-field" }
quests[98172] = { id = 98172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trailing Xal'atath", description = "We must not lose sight of our true goal here in Silvermoon, {name}: to bring Xal'atath to justice.\n\nWe all saw her void armies at the Sunwell. They were rushing downward, INTO the well, a thousand a minute. And now: silence.\n\nListen for their whispers, {class}. With any luck, we'll pick up on their trail again, and then we'll find Xal'atath... and perhaps even those that pursued her.", sourceObjective = "Collect 100 Fading Voidwhispers.\n\nThese remnants of the Void can be looted from dungeons, delves, treasures, and other dangerous creatures.", progress = "Every whisper silenced is a step closer towards our true quarry.", completion = "Our hunt is far from over.\n\nKeep your ears and eyes open, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[98204] = { id = 98204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Keepsake", description = "<A containment shield hums, wrapping tightly about the keepsake. The object projects an aura of sorrow and suffering.\n\nAccording to the Last Architect, this keepsake is cursed, but it can be cleansed. One must simply fold their essence inside that of the object and remove the corruption from within. How dangerous could it be?>", sourceObjective = "Cleanse the keepsake by removing its corruption.", progress = "To remove the corruption from the cursed keepsake directly, one must enter within and do battle with the echoes of the trauma haunting it. Once extracted, the corruption can be destroyed.", completion = "The keepsake has been cleansed! It is ready for a new home, where better memories can be made.", sourceObjectiveStatus = "unverified-source-field" }
quests[98210] = { id = 98210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (90) E" }
quests[98212] = { id = 98212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (90) E" }
quests[98213] = { id = 98213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (90) E" }
quests[98218] = { id = 98218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Amani'Zar", description = "{name},\n\nYour aid is requested in Amani'Zar Village. Please meet me there.\n\n--Liadrin", sourceObjective = "Speak to Liadrin in Amani'Zar Village.", completion = "Good, you're here.", sourceObjectiveStatus = "unverified-source-field" }
quests[98226] = { id = 98226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venomous Abyss: Deception Unmasked", description = "If my brother is no longer bowing to Malacrass, then he's in grave danger. We need to find a way to get to dem as quickly as possible. Look for anything that could let us get through de temple faster.", sourceObjective = "Collect 3 Mask Fragments within the Venomous Abyss on Normal difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[98228] = { id = 98228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venomous Abyss: Deception Unmasked", description = "If my brother is no longer bowing to Malacrass, then he's in grave danger. We need to find a way to get to dem as quickly as possible. Look for anything that could let us get through de temple faster.", sourceObjective = "Collect 3 Mask Fragments within The Venomous Abyss on Heroic difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[98229] = { id = 98229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venomous Abyss: Deception Unmasked", description = "If my brother is no longer bowing to Malacrass, then he's in grave danger. We need to find a way to get to dem as quickly as possible. Look for anything that could let us get through de temple faster.", sourceObjective = "Collect 3 Mask Fragments within the Venomous Abyss on Mythic difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[98232] = { id = 98232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Vaults of Atal'Utek", description = "Zul'jarra's forces stand watch at the gates of the Vaults of Atal'Utek, holding the line against those wicked serpents.\n\nThe fate of the entire Eastern Kingdoms rests on their blades. We would do well to provide them with reinforcements. The Children of Ula'tek are fierce, but they are no match for a seasoned {class} like you.\n\nTraverse the temple and thin their ranks, however you can.", sourceObjective = "Complete Temple Strikes, Incursions, and defeat Ancient Foes in the Vaults of Atal'Utek.", completion = "That should keep their numbers down, for a little while at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[98234] = { id = 98234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Week 1 of 3: Gladiator's Distinction", description = "Interested in training against some of our fighters? Step into the ring and show us your mettle.\n\nMake sure you equip these medallions, and defeat at least two teams of enemies.", sourceObjective = "Win arenas or battlegrounds within Training Grounds with PvP trinkets equipped.", progress = "You have yet to finish your training for the week.", completion = "Excellent work. Always utilize your Gladiator's Medallion or you'll get crushed out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[98295] = { id = 98295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Week 2 of 3: Crowd Control", description = "Good work using your Gladiator's Distinction bonus. Now I want you to try defeating some enemy teams after landing a crowd control effect!", sourceObjective = "Win arenas or battlegrounds within Training Grounds after using crowd control.", completion = "Excellent work. Crowd control is a key component of victory.", sourceObjectiveStatus = "unverified-source-field" }
quests[98311] = { id = 98311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Week 3 of 3: Interrupts and Dispels", description = "I have one final lesson for you. Get in there and interrupt an enemy spell cast, or dispel a harmful effect from yourself or an ally. Then, defeat your enemy two more times.", sourceObjective = "Win arenas or battlegrounds within Training Grounds after using an interrupt or dispel.", progress = "You have yet to finish your training for the week.", completion = "Excellent work. Interrupts and dispels are the final piece of the puzzle.", sourceObjectiveStatus = "unverified-source-field" }
quests[98343] = { id = 98343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom Fishing: My Second-Best", description = "Before I send ye out hunting, ye should acquaint yerself with what remains of my crew.\n\nMost perished in the wreck, of course. Others fell into the swamp. Some traitorous gits... well, we'll get to them in a moment, won't we?\n\nBut me loyal second mate is holding down the fort, just down river of me Landing. She'll set you up right.", sourceObjective = "Meet with Second Mate Sluggs at Tokka's Folly.", completion = "Oh, the Captain sent you? Well, isn't that a n-nice surprise.", sourceObjectiveStatus = "unverified-source-field" }
quests[98388] = { id = 98388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Vaults of Atal'Utek", description = "Past dis bulwark, there's nothin but snakes, spirits, and venomous death.\n\nI've lost three lieutenants dis week. Strong ones. Brave ones. Maybe stronger and braver than you.\n\n<Warleader Abdumati looks you over with a weary eye.>\n\nIf you want to fling yaself into de abyss, be my guest. Bring back my scouts, if you can find dem amongst de bones.\n\nBut watch your step. Dat venom will swallow you whole.", sourceObjective = "Find what's become of Naz'ara the Brave, Hawkeye Socho, and Commander Gazba.", progress = "Don't make me send someone out to rescue you. I don't have de fighters for dat.", completion = "Well... two outta three ain't bad, not for here.\n\nYou're lookin' a bit green, though. Sure dat venom didn't get to ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[98406] = { id = 98406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curated Gift", description = "I have watched the effort and care you take with the other mortals of your neighborhood, here in Razorwind Shores. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind.\n\nIn recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", sourceObjective = "Accept a gift from the Last Architect.", completion = "I have watched the effort and care you take with the other mortals of your neighborhood. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind.\n\nIn recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", sourceObjectiveStatus = "unverified-source-field" }
quests[98414] = { id = 98414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Request from the Captain", description = "Oh, uh. The Captain has requested you join him at Tokka's Landing as soon as you can.\n\n<Second Mate Sluggs quivers in her shell.>\n\nHe had a mean look about him. Tread lightly.", sourceObjective = "Meet with Captain Tokka at Tokka's Landing.", completion = "Ye lookin' for more work? Ye were so helpful last time.", sourceObjectiveStatus = "unverified-source-field" }
quests[98415] = { id = 98415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor to the Captain", description = "Oh! While you were out fishing, Captain Tokka asked to see you again. I think he's beginning to trust you.\n\n<Second Mate Sluggs grimaces.>\n\nThe Captain's trust d-does tend to come with caveats.", sourceObjective = "Meet with Captain Tokka at Tokka's Landing.", completion = "I've another task for you. Each more grisly than the last, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[98416] = { id = 98416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plea from the Captain", description = "Ohh, the Captain's really in a foul mood this time. I think you'd better go see what he wants.\n\n<Second Mate Sluggs shakes her head.>\n\nYou're the only one who can soothe his storms, these days.", sourceObjective = "Meet with Captain Tokka at Tokka's Landing.", completion = "I've got a whale of a task for you this time, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[98419] = { id = 98419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoulder to Shoulder", sourceObjective = "Form a party with other players and slay foes in the Vaults of Atal'Utek.", progress = "Dis is a war, {name}. No one should fight alone.", completion = "Shoulder to shoulder. Dat's de way we win dis battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[98420] = { id = 98420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Out There?", description = "Knowledge is de most important weapon in war. These Vaults are ancient and vast--our scouts cannot see everything. What lurks in de depths of these corrupted halls?\n\nDat's precisely what I need to know. Get out there and tell me what you see, but it's dangerous to go alone. You best bring some comrades if you want to make it back.", sourceObjective = "Form a party with other players and scout the Vaults of Atal'Utek.", completion = "De fiends here think dey can lurk and scheme in de dark. We will root dem out and purge dem from these lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[98428] = { id = 98428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaults of Atal'Utek: The Altar of Corrosion", description = "De Altar of Corrosion.\n\nWho can say when dis accursed piece of stone rose out of de venom? I have studied it for lifetimes and have only just tasted its power.\n\n<Er'inye licks her spectral lips.>\n\nSay de word, and I will convert de corrosion you carry to something more useful. Den, you may commune with de Altar and accept its many gifts.", sourceObjective = "Speak with Er'inye to corrode your spirit, then commune with the Altar of Corrosion.", progress = "De curse claims us all in different ways.", completion = "How does it feel? Unearthly? Decadent?\n\nI would give up much to be able to taste it again for the first time.", sourceObjectiveStatus = "unverified-source-field" }
quests[98473] = { id = 98473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Autumnal Addresses", description = "Race through the checkpoint rings marking the course.", sourceObjective = "Ride through the rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[98474] = { id = 98474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runetotem Run", description = "Race through the checkpoint rings marking the course.", sourceObjective = "Ride through the rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[98515] = { id = 98515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaults of Atal'Utek: A Toxic Tour", description = "Dis temple is where all de Children of Ula'tek first crawl out of de ooze. Dis is where we hold de line.\n\nDe threat comes in waves. Sometimes short strikes. Sometimes an incursion dat overwhelms de whole temple. Sometimes a huge monstrosity rising out of de venom.\n\nWhatever dey send, send it back cryin' to its big evil mama!\n\nAnd in de meantime, do what you can to keep our patrols safe.", sourceObjective = "Complete a Patrol, a Strike, an Incursion, and defeat an Ancient Foe within the Vaults of Atal'Utek.", completion = "You're getting a hang for de rhythm of dis awful place, eh?\n\nSnakes crawl out of de venom pit, and we throw dem right back in.", sourceObjectiveStatus = "unverified-source-field" }
